head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > preventCopyPaste]<br/>입력값에 대한 복사, 잘라내기, 붙여넣기를 금지할지 설정합니다.",
    "validation" : [
        "미설정 시 기본값 false 로 동작하여 복사, 잘라내기, 붙여넣기를 허용합니다.",
        "true 설정 시 복사, 잘라내기, 붙여넣기를 금지합니다.",
        "false (default) 설정 시 복사, 잘라내기, 붙여넣기를 허용합니다.",
        "컴포넌트가 비활성화(disabled) 상태일때도 적용됩니다.",
        "컴포넌트가 readonly 상태일때도 적용됩니다.",
        "단, 비활성화(disabled) 상태일때 최신 웹브라우저에서 지원하는 선택과 복사는 막을 수 없습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 재생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof target2 !== 'undefined') {
        target2.remove();
    }

    if (typeof target3 !== 'undefined') {
        target3.remove();
    }

    if (typeof paste_input !== 'undefined') {
        paste_input.remove();
    }

    let preventCopyPaste = con_preventCopyPaste.getText();

    // 조건 설정 (style 은 createBasicSearchBox 내부에서 자동 부여 → 중복 정의 금지)
    let properties = {
        disabled: true,
        preventCopyPaste: preventCopyPaste,
        initValue: "disabled=true",
    }

    let properties2 = {
        readOnly: true,
        preventCopyPaste: preventCopyPaste,
        initValue: "readonly=true",
    }

    let properties3 = {
        preventCopyPaste: preventCopyPaste,
        initValue: "searchbox",
    }

    let cList = $c.gcm.createCList(properties);
    let cList2 = $c.gcm.createCList(properties2);
    let cList3 = $c.gcm.createCList(properties3);

    await $c.gcm.createBasicSearchBox(cList, '', 'target1');
    await $c.gcm.createBasicSearchBox(cList2, '', 'target2');
    await $c.gcm.createBasicSearchBox(cList3, '', 'target3');

    // 복사 값 붙여넣기 테스트 용 input 생성 (복사할 초기값 설정)
    await $c.gcm.createBasicInput('', '', 'paste_input');
    paste_input.setValue("test");
}



// 각 target/입력창의 현재 값을 출력
scwin.btn_getReturn_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1 (disabled=true)  text : " + target1.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue("target2 (readonly=true)  text : " + target2.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue("target3 (searchbox)      text : " + target3.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue("paste_input              text : " + paste_input.getValue());
};
